    const x = u;
    const y = v;
    if (funcType === 'paraboloid') {
        return x * x - y * y;
    } else if (funcType === 'cone') {
        return Math.sqrt(x * x + y * y);
    } else if (typeof funcType === 'function') {
        return funcType(x, y);
    } else {
        throw new Error("Unsupported function type. Choose 'paraboloid', 'cone', or provide a custom function.");
    }
}

function createParametricGeometry(funcType) {
    const geometry = new THREE.ParametricGeometry(
        function(u, v) {
            const step = 0.1;
            const x = (u * 2 - 1); // Map u from [0, 1] to [-1, 1]
            const y = (v * 2 - 1); // Map v from [0, 1] to [-1, 1]
            const z = f(x, y, funcType);
            return new THREE.Vector3(x, y, z);
        },
        20, 20 // Number of segments in the u and v directions
    );
    return geometry;
}

function initScene(funcType) {
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer();
    renderer.setSize(window.innerWidth, window.innerHeight);
