<script>
    // Scene setup
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    // Sun
    const sunGeometry = new THREE.SphereGeometry(5, 32, 32);
    const sunMaterial = new THREE.MeshStandardMaterial({ color: 0xffcc00, emissive: 0xffcc00, emissiveIntensity: 1.0 });
    const sun = new THREE.Mesh(sunGeometry, sunMaterial);
    scene.add(sun);

    // Light
    const light = new THREE.PointLight(0xffffff, 1, 1000);
    light.position.set(0, 0, 0);
    scene.add(light);

    // Fetch planetary data from JSON
    fetch('planetary_data.json')
        .then(response => response.json())
        .then(data => {
            data.forEach(planetData => {
                const geometry = new THREE.SphereGeometry(planetData.radius / 1000, 32, 32); // Scale down radius
                const material = new THREE.MeshStandardMaterial({ color: 0x00ff00 }); // Default color, can be customized
                const planet = new THREE.Mesh(geometry, material);
                planet.position.x = planetData.distance * 10; // Scale distance
                scene.add(planet);

                planet.orbit = planetData.distance * 10;
                planet.period = planetData.period;
            });

            function animate() {
                requestAnimationFrame(animate);

                data.forEach((planetData, index) => {
                    const planet = scene.children[index + 1]; // Skip the sun
                    planet.rotation.y += 0.01;
                    planet.position.x = Math.cos(Date.now() * planetData.period * 0.001) * planetData.orbit;
                    planet.position.z = Math.sin(Date.now() * planetData.period * 0.001) * planetData.orbit;
                });

                renderer.render(scene, camera);
            }

            animate();
        })
        .catch(error => console.error('Error loading planetary data:', error));

    camera.position.z = 100;

    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // Post-processing
    const composer = new THREE.EffectComposer(renderer);
    const renderPass = new THREE.RenderPass(scene, camera);
    const bloomPass = new THREE.UnrealBloomPass(new THREE.Vector2(window.innerWidth, window.innerHeight), 1.5, 0.4, 0.85);
    composer.addPass(renderPass);
    composer.addPass(bloomPass);

    function render() {
        composer.render();
    }

    function animate() {
        requestAnimationFrame(animate);
        data.forEach((planetData, index) => {
            const planet = scene.children[index + 1]; // Skip the sun
            planet.rotation.y += 0.01;
            planet.position.x = Math.cos(Date.now() * planetData.period * 0.001) * planetData.orbit;
            planet.position.z = Math.sin(Date.now() * planetData.period * 0.001) * planetData.orbit;
        });
        render();
    }

    animate();
</script>
