    walk(ip, "");
    iput(ip);
    return 0;
}

void walk(struct inode *ip, char *prefix) {
    struct dirent de;
    char path[NAME_MAX + 1];
    for (uint off = 0; dirlookup(ip, off, &de, 0) > 0; off += sizeof(de)) {
        if (de.inum == 0) {
            continue;
        }
        memmove(path, prefix, strlen(prefix));
        strncat(path, de.name, NAME_MAX);
        strncat(path, "/", 1);
        struct inode *child_ip = iget(ip->dev, de.inum);
        if (S_ISDIR(child_ip->type)) {
            printf("Directory: %s, Inode: %d\n", path, child_ip->inum);
            walk(child_ip, path);
        } else {
            printf("File: %s, Inode: %d\n", path, child_ip->inum);
        }
        iput(child_ip);
    }
}

int sys_imapWalker(void) {
    struct superblock sb;
    readsb(ROOTDEV, &sb);
    for (uint i = 1; i < sb.ninodes; i++) {
        struct inode *ip = iget(ROOTDEV, i);
        if (ip->type != 0) {
            printf("Inode: %d\n", i);
        }
        iput(ip);
    }
    return 0;
}

int sys_inodeReader(void) {
    int inum;
    argint(0, &inum);
    if (inum <= 0) {
        return -1;
    }
    struct inode *ip = iget(ROOTDEV, inum);
    if (ip == NULL || ip->type == 0) {
        return -1;
    }
    printf("Inode: %d\n", ip->inum);
    printf("Size: %d bytes\n", ip->size);
    printf("Type: %d\n", ip->type);
    printf("Nlink: %d\n", ip->nlink);
    printf("Last Modified: %d\n", ip->mtime);
    iput(ip);
    return 0;
}

int sys_erase_inode_and_file(void) {
    int inum;
    argint(0, &inum);
    if (inum <= 0) {
        return -1;
    }
    struct inode *ip = iget(ROOTDEV, inum);
    if (ip == NULL || ip->type == 0) {
        return -1;
    }
    if (S_ISDIR(ip->type)) {
        rmdir(ip);
    } else {
        remove(ip);
    }
    iput(ip);
    return 0;
}
