#### Indirect Block Damage

**Approach**:
1. **Read Direct Blocks**: Read the direct blocks from inodes.
2. **Follow Block Pointers**: Follow the block pointers to reconstruct indirect blocks.
3. **Ensure Integrity**: Ensure the indirect blocks are correctly linked and referenced.

**Implementation**:
```c
// fs.c
int sys_recoverIndirectBlocks(void) {
    struct superblock sb;
    readsb(ROOTDEV, &sb);

    for (uint i = 1; i < sb.ninodes; i++) {
        struct inode *ip = iget(ROOTDEV, i);
        if (ip->type != 0) {
            for (int j = 0; j < NDIRECT + NINDIRECT; j++) {
                if (ip->addrs[j] != 0) {
                    struct buf *bp = bread(ROOTDEV, ip->addrs[j]);
                    if (j < NDIRECT) {
                        // Direct block
                        if (bp->valid) {
                            continue;
                        }
                        // Reallocate and copy data
                        int new_block = balloc(ROOTDEV);
                        struct buf *new_bp = bread(ROOTDEV, new_block);
                        memmove(new_bp->data, bp->data, BSIZE);
                        bwrite(new_bp);
                        brelse(new_bp);
                        ip->addrs[j] = new_block;
                    } else {
                        // Indirect block
                        int *indirect = (int *)bp->data;
                        for (int k = 0; k < BSIZE / sizeof(int); k++) {
                            if (indirect[k] != 0) {
                                struct buf *ibp = bread(ROOTDEV, indirect[k]);
                                if (ibp->valid) {
                                    continue;
                                }
                                // Reallocate and copy data
                                int new_block = balloc(ROOTDEV);
                                struct buf *new_ibp = bread(ROOTDEV, new_block);
                                memmove(new_ibp->data, ibp->data, BSIZE);
                                bwrite(new_ibp);
                                brelse(new_ibp);
                                indirect[k] = new_block;
                            }
                        }
                        bwrite(bp);
                    }
                    brelse(bp);
                }
            }
        }
        iput(ip);
    }

    printf("Indirect blocks recovered successfully.\n");
    return 0;
}
