#include <SFML/Graphics.hpp>
#include "Game.h"
#include "Observer.h"

class UI : public Observer {
public:
    UI(Game& game);
    void run();

private:
    Game& game;
    sf::RenderWindow window;
    sf::Font font;
    sf::Text text;

    void drawBoard();
    void drawButtons();
