void PlayerRating::saveToFile(const std::string& filename) {
    std::ofstream file(filename);
    for (const auto& entry : totalGames) {
        file << entry.first << " " << wins[entry.first] << " " << losses[entry.first] << " " << entry.second << "\n";
    }
    file.close();
}

void PlayerRating::loadFromFile(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) return;

    std::string line;
    while (std::getline(file, line)) {
        std::istringstream iss(line);
        std::string player;
        int win, loss, total;
        if (iss >> player >> win >> loss >> total) {
            wins[player] = win;
            losses[player] = loss;
            totalGames[player] = total;
        }
    }
    file.close();
}

