        pendingPhotoList.setOnItemClickListener(new AdapterView.OnItemClickListener() {
            @Override
            public void onItemClick(AdapterView<?> parent, View view, int position, long id) {
                final PendingPhoto selectedPhoto = pendingPhotoListItems.get(position);

                Button approveButton = new Button(AdminPanelActivity.this);
                approveButton.setText("Approve");
                approveButton.setOnClickListener(new View.OnClickListener() {
                    @Override
                    public void onClick(View v) {
                        approvePhoto(selectedPhoto.getId());
                    }
                });

                Button rejectButton = new Button(AdminPanelActivity.this);
                rejectButton.setText("Reject");
                rejectButton.setOnClickListener(new View.OnClickListener() {
                    @Override
                    public void onClick(View v) {
                        rejectPhoto(selectedPhoto.getId());
                    }
                });

                // Show the buttons (you can use a dialog or a custom view)
                // For simplicity, we'll just toast the action
                Toast.makeText(AdminPanelActivity.this, "Selected: " + selectedPhoto.getName(), Toast.LENGTH_SHORT).show();
            }
        });

        backButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                finish();
            }
        });
    }

    private void loadPendingPhotos() {
        String url = "http://your_flask_server_address/admin/pending";
        JsonArrayRequest request = new JsonArrayRequest(Request.Method.GET, url, null,
            new Response.Listener<JSONArray>() {
                @Override
                public void onResponse(JSONArray response) {
                    pendingPhotoListItems.clear();
                    for (int i = 0; i < response.length(); i++) {
                        try {
                            JSONObject jsonObject = response.getJSONObject(i);
                            PendingPhoto photo = new PendingPhoto(
                                jsonObject.getInt("id"),
                                jsonObject.getString("name"),
                                jsonObject.getDouble("price"),
                                jsonObject.getString("description"),
                                jsonObject.getString("photo_url")
                            );
                            pendingPhotoListItems.add(photo);
                        } catch (JSONException e) {
                            e.printStackTrace();
                        }
                    }
                    pendingPhotoAdapter.notifyDataSetChanged();
                }
            },
            new Response.ErrorListener() {
                @Override
                public void onErrorResponse(VolleyError error) {
                    Toast.makeText(AdminPanelActivity.this, "Error loading pending photos", Toast.LENGTH_SHORT).show();
                }
            }
        );

        requestQueue.add(request);
    }

    private void approvePhoto(int photoId) {
        String url = "http://your_flask_server_address/admin/approve";
        StringRequest request = new StringRequest(Request.Method.POST, url,
            new Response.Listener<String>() {
                @Override
                public void onResponse(String response) {
                    Toast.makeText(AdminPanelActivity.this, "Photo approved: " + response, Toast.LENGTH_SHORT).show();
                    loadPendingPhotos();
                }
            },
            new Response.ErrorListener() {
                @Override
                public void onErrorResponse(VolleyError error) {
                    Toast.makeText(AdminPanelActivity.this, "Error approving photo", Toast.LENGTH_SHORT).show();
                }
            }) {
            @Override
            protected Map<String, String> getParams() {
                Map<String, String> params = new HashMap<>();
                params.put("photo_id", String.valueOf(photoId));
                return params;
            }
        };

        requestQueue.add(request);
    }

    private void rejectPhoto(int photoId) {
        String url = "http://your_flask_server_address/admin/reject";
        StringRequest request = new StringRequest(Request.Method.POST, url,
            new Response.Listener<String>() {
                @Override
                public void onResponse(String response) {
                    Toast.makeText(AdminPanelActivity.this, "Photo rejected: " + response, Toast.LENGTH_SHORT).show();
                    loadPendingPhotos();
                }
            },
            new Response.ErrorListener() {
                @Override
                public void onErrorResponse(VolleyError error) {
                    Toast.makeText(AdminPanelActivity.this, "Error rejecting photo", Toast.LENGTH_SHORT).show();
                }
            }) {
            @Override
            protected Map<String, String> getParams() {
                Map<String, String> params = new HashMap<>();
                params.put("photo_id", String.valueOf(photoId));
                return params;
            }
        };

        requestQueue.add(request);
    }
}

class PendingPhoto {
    private int id;
    private String name;
    private double price;
    private String description;
    private String photoUrl;

    public PendingPhoto(int id, String name, double price, String description, String photoUrl) {
        this.id = id;
        this.name = name;
        this.price = price;
        this.description = description;
        this.photoUrl = photoUrl;
    }

    public int getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public double getPrice() {
        return price;
    }

    public String getDescription() {
        return description;
    }

    public String getPhotoUrl() {
        return photoUrl;
    }
}

class PendingPhotoAdapter extends ArrayAdapter<PendingPhoto> {
    private Context context;
    private List<PendingPhoto> pendingPhotos;

    public PendingPhotoAdapter(Context context, List<PendingPhoto> pendingPhotos) {
        super(context, 0, pendingPhotos);
        this.context = context;
        this.pendingPhotos = pendingPhotos;
    }

    @Override
    public View getView(int position, View convertView, ViewGroup parent) {
        if (convertView == null) {
            convertView = LayoutInflater.from(context).inflate(R.layout.list_item_photo, parent, false);
        }

        PendingPhoto pendingPhoto = pendingPhotos.get(position);

        ImageView photoImage = convertView.findViewById(R.id.photo_image);
        TextView photoName = convertView.findViewById(R.id.photo_name);
        TextView photoPrice = convertView.findViewById(R.id.photo_price);
        TextView photoDescription = convertView.findViewById(R.id.photo_description);

        Glide.with(context).load(pendingPhoto.getPhotoUrl()).into(photoImage);
        photoName.setText(pendingPhoto.getName());
        photoPrice.setText("Price: " + pendingPhoto.getPrice());
        photoDescription.setText("Description: " + pendingPhoto.getDescription());

        return convertView;
    }
}
