#### Step 4: Create a Multi-Page System

To manage different documentation files, we'll use dynamic routing in Next.js. Create a new file `pages/[slug].js` to handle dynamic routes:

```javascript
// pages/[slug].js
'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { db } from '@/lib/firebase';
import { doc, getDoc, setDoc } from 'firebase/firestore';
import { Markdown } from 'markdown-react-x';
import Editor from '@/components/Editor';

export default function DocumentPage() {
  const router = useRouter();
  const { slug } = router.query;
  const [content, setContent] = useState('');

  useEffect(() => {
    if (slug) {
      fetchDocument(slug);
    }
  }, [slug]);

  const fetchDocument = async (slug) => {
    const docRef = doc(db, 'documents', slug);
    const docSnap = await getDoc(docRef);
    if (docSnap.exists()) {
      setContent(docSnap.data().content);
    } else {
      setContent('');
    }
  };

  const saveDocument = async () => {
    const docRef = doc(db, 'documents', slug);
    await setDoc(docRef, { content });
  };

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-2xl font-bold mb-4">{slug}</h1>
      <Markdown>{content}</Markdown>
      <Editor content={content} onChange={setContent} onSave={saveDocument} />
    </div>
  );
}
```

