        Vector3[] positions = new Vector3[segmentCount];
        Vector2 velocity = direction * predictionForce;
        Vector2 initialVelocity = velocity;

        for (int i = 0; i < segmentCount; i++)
        {
            float time = i * 0.1f; // Time step for each segment
            Vector2 position = initialPosition + velocity * time + 0.5f * gravity * Vector3.up * time * time;

            // Apply drag and mass to the velocity
