        return false;
    }

    if (EVP_VerifyUpdate(ctx, message.c_str(), message.size()) != 1) {
        std::cerr << "Failed to update verification context.\n";
        EVP_MD_CTX_free(ctx);
        EVP_PKEY_free(public_key);
        return false;
    }

    unsigned char* sig = (unsigned char*)base64_decode(signature).c_str();
    int result = EVP_VerifyFinal(ctx, sig, signature.size(), public_key);

    EVP_MD_CTX_free(ctx);
    EVP_PKEY_free(public_key);

    if (result == 1) {
        std::cout << "Descriptor signature verified successfully.\n";
        return true;
    } else {
        std::cerr << "Descriptor signature verification failed.\n";
        return false;
    }
}

// Base64 decoding function
std::string base64_decode(const std::string& encoded_string) {
    BIO* bio, * b64;
    BUF_MEM* buffer_ptr;

    b64 = BIO_new(BIO_f_base64());
    bio = BIO_new_mem_buf(encoded_string.c_str(), -1);
    bio = BIO_push(b64, bio);

    BIO_set_flags(bio, BIO_FLAGS_BASE64_NO_NL); // Ignore newlines to handle strings passed via command line
    BUF_MEM* buffer = NULL;
    BIO_get_mem_ptr(bio, &buffer);
    BIO_set_close(bio, BIO_NOCLOSE);
    BIO_free_all(bio);

    char* buf = new char[buffer->length];
    memcpy(buf, buffer->data, buffer->length);
    std::string ret(buf, buffer->length);
    delete[] buf;
    BUF_MEM_free(buffer);

    return ret;
}

