```csharp
using System;
using Autodesk.AdvanceSteel.CADAccess;
using Autodesk.AdvanceSteel.Geometry;
using Autodesk.AdvanceSteel.Drawing;
using Autodesk.AdvanceSteel.DocumentManager;

public class DimensionHolesCartesian
{
    public static void DimensionHolesCartesian(string plateId)
    {
        // Get the current document
        Document doc = DocumentManager.MdiActiveDocument;

        // Start a new transaction to manage changes
        Transaction tr = doc.TransactionManager.StartTransaction();

        try
        {
            // Get the plate object using its ID
            AsPlate plate = (AsPlate)doc.Database.GetObject(plateId);

            // Get the bounding box of the plate to determine the origin (left bottom corner)
            BoundingBox bbox = plate.GetBoundingBox();
            double minX = bbox.MinPoint.X;
            double minY = bbox.MinPoint.Y;

            // Get the holes on the plate
            AsHoleCollection holes = plate.GetHoleCollection();

            foreach (AsHole hole in holes)
            {
                // Calculate the relative position of the hole
                Point3d holePos = hole.GetPosition();
                double relX = holePos.X - minX;
                double relY = holePos.Y - minY;

                // Create a point for the dimension
                Point3d dimPoint = new Point3d(relX, relY, 0);

                // Create the dimension text
                string dimText = $"X: {relX}, Y: {relY}";

                // Create the dimension object
                AsDimension dim = AsDimension.Create(doc, dimPoint, dimText);

                // Set the dimension properties (optional)
                dim.SetProperties(AsDimensionType.Horizontal, AsDimensionJustification.Middle, AsDimensionArrowType.FilledSmall);

                // Add the dimension to the drawing
                doc.Database.AddEntity(dim);
            }

            // Commit the transaction to apply changes
            tr.Commit();
        }
        catch (Exception ex)
        {
            // Rollback the transaction if an error occurs
            tr.Abort();
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
        finally
