import android.os.AsyncTask;
import android.os.Build;
import android.os.Bundle;
import android.util.Log;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;

import androidx.appcompat.app.AppCompatActivity;

import com.jcraft.jsch.ChannelExec;
import com.jcraft.jsch.JSch;
import com.jcraft.jsch.Session;

public class MainActivity extends AppCompatActivity {

    private Button btnUp;
    private EditText txtAddress;
    public static String wifiModuleIp;
    public static int wifiModulePort;
    public static String CMD;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        btnUp = findViewById(R.id.btnUp);
        txtAddress = findViewById(R.id.ipAddress);

        btnUp.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                // Set the wifiModuleIp and wifiModulePort variables to the Raspberry Pi's IP address and SSH port, respectively
                wifiModuleIp = "192.168.1.100";
                wifiModulePort = 22;

                // Set the CMD variable to the command to execute the Python script
                CMD = "python /path/to/script.py";

                // Execute the command on the Raspberry Pi using SSH
                Soket_AsyncTask task = new Soket_AsyncTask();
                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
                    task.executeOnExecutor(AsyncTask.THREAD_POOL_EXECUTOR);
                } else {
                    task.execute();
                }
            }
        });
    }

    private class Soket_AsyncTask extends AsyncTask<Void, Void, String> {

        private static final String USER = "pi";
        private static final String PRIVATE_KEY_PATH = "/path/to/private/key";
        private static final int TIMEOUT = 10000;

        @Override
        protected String doInBackground(Void... voids) {
            try {
                JSch jsch = new JSch();
                jsch.addIdentity(PRIVATE_KEY_PATH);

                Session session = jsch.getSession(USER, wifiModuleIp, wifiModulePort);
                session.setConfig("StrictHostKeyChecking", "no");
                session.connect(TIMEOUT);

                ChannelExec channelExec = (ChannelExec) session.openChannel("exec");
                channelExec.setCommand(CMD);
                channelExec.setInputStream(null);
                channelExec.setErrStream(System.err);

                InputStream in = channelExec.getInputStream();
                channelExec.connect();

                byte[] tmp = new byte[1024];
                StringBuilder output = new StringBuilder();
                while (true) {
                    while (in.available() > 0) {
                        int i = in.read(tmp, 0, 1024);
                        if (i < 0) break;
                        output.append(new String(tmp, 0, i));
                    }
                    if (channelExec.isClosed()) {
                        if (in.available() > 0) continue;
                        break;
                    }
                    try {
                        Thread.sleep(1000);
                    } catch (Exception ee) {
                    }
                }

                channelExec.disconnect();
                session.disconnect();

                return output.toString();
            } catch (Exception e) {
                e.printStackTrace();
                return "Error: " + e.getMessage();
            }
        }

        @Override
        protected void onPostExecute(String result) {
            // Handle the result here
            Log.d("Soket_AsyncTask", "Result: " + result);
        }
    }
}
